import {generateStarterLibrary,removeLegacyStarter} from './starter-data.js';
import {readLibrary,exportLibrary,speakText,stopSpeech,createSaveCoordinator,decodeLibrary} from './storage.js';
import {uid,DAY,shuffle,correct,face,schedule,intervalLabel,queue,makeTest,grade,parseDelimited,validateLibrary} from './engine.js';
const app=document.querySelector('#app');
const icons={book:'<rect x="7" y="3" width="10" height="17" rx="1.4" fill="var(--ground,#f6f5ef)" transform="rotate(-18 12 21)"/><rect x="7" y="3" width="10" height="17" rx="1.4" fill="var(--tint,#e8eee6)"/><g transform="rotate(18 12 21)"><rect x="7" y="3" width="10" height="17" rx="1.4" fill="var(--ground,#f6f5ef)"/><path d="M9.5 8h5M9.5 11h3"/></g>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="m9 5 7 7-7 7"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9z"/>',sound:'<path d="M4 9h4l5-5v16l-5-5H4zM17 8a6 6 0 0 1 0 8M20 5a10 10 0 0 1 0 14"/>',swap:'<path d="M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.book}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,selected,view='deck',mode='flashcards',direction='forward',starOnly=false,strict=false,random=false,search='',session=null,draft=null,editorDraftId=null,draftBaseFingerprint=null,timer=null,dirty=false,saveError='',status='Saved on this device',testTypes=['choice','written','tf','matching'],testCount=10,occlusion=null;
const saver=createSaveCoordinator({snapshot:()=>data,onState:s=>{dirty=s.dirty;saveError=s.error?.message||'';status=saveError?'Save failed • export a backup':s.pending||s.dirty?'Saving…':'Saved on this device';updateStatus()}});
const modes=[['flashcards','Flashcards'],['review','Spaced review'],['learn','Learn'],['write','Write'],['spell','Spell'],['test','Test'],['match','Match'],['gravity','Falling words'],['sprint','Quick quiz'],['blocks','Blocks'],['charms','Charms'],['party','Pass & play']];
const lastShown=new Map(),shuffleByDefault=new Set(['flashcards','learn','write','spell']);
const shuffleChoice=(deckId,modeId)=>modeId==='review'?true:data.studyPreferences?.find(p=>p.deckId===deckId&&p.mode===modeId)?.shuffle??shuffleByDefault.has(modeId);
function setShuffleChoice(deckId,modeId,value){const prefs=data.studyPreferences||[];data.studyPreferences=prefs;const item=prefs.find(p=>p.deckId===deckId&&p.mode===modeId);if(item)item.shuffle=value;else prefs.push({deckId,mode:modeId,shuffle:value})}
function shuffleCycle(list,previous){const result=shuffle(list);if(result.length>1&&previous&&result[0].id===previous){const other=1+Math.floor(Math.random()*(result.length-1));[result[0],result[other]]=[result[other],result[0]]}return result}
function visibleFaceKey(text,image){return JSON.stringify([text||'',image||''])}
const studyDirection=()=>session?.direction||direction;

const deck=()=>data.decks.find(d=>d.id===selected);
const cards=()=> (deck()?.cards||[]).filter(c=>!c.suspended&&(!starOnly||c.starred));
function stop(){if(mode==='test'&&session?.questions)rememberTest();if(timer){clearInterval(timer);timer=null}stopSpeech();session=null}
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),4500)}
function save(){saver.request();return saver.flush().then(ok=>{if(!ok)toast(`Could not save: ${saveError}. Your changes are still in this window; export a backup.`);return ok})}
function updateStatus(){document.querySelectorAll('[data-status]').forEach(x=>{x.textContent=status;x.classList.toggle('error-text',!!saveError)})}
function btn(action,label,cls='',attrs=''){return `<button class="${cls}" data-action="${action}" ${attrs}>${label}</button>`}
function additionalInfo(text){return text?.trim()?`<p class="additional-info">${esc(text)}</p>`:''}
function media(text,img,cls=''){return `<div class="face ${cls}">${img?`<img src="${esc(img)}" alt="${esc(text||'Study image')}" loading="lazy">`:''}${text?`<div>${esc(text)}</div>`:''}</div>`}
function shell(body){closeLibraryMenu();const d=deck();app.innerHTML=`<aside class="sidebar"><a class="brand" href="#" data-action="home">${icon('book')}<span>freezlit<span class="brand-dot">.</span></span></a><div class="sidebar-heading"><span>Your library</span>${btn('new-deck',icon('plus'),'icon-button','aria-label="Create a deck"')}</div><nav aria-label="Deck library">${data.decks.map(x=>`<button class="deck-link ${selected===x.id?'active':''}" data-action="select" data-id="${esc(x.id)}"><span class="deck-dot ${esc(x.color||'green')}"></span><span>${esc(x.title)}</span><small>${x.cards.length}</small></button>`).join('')||'<p class="muted">No decks yet. Create your first one.</p>'}</nav><div class="sidebar-footer">${btn('import','Import cards','wide secondary')}${btn('backup',icon('download')+' Export library','wide ghost')}${btn('settings',icon('settings')+' Settings & storage','wide ghost')}</div></aside><main>${body}</main>`}
function overview(){const d=deck();if(!d){shell(`<section class="empty"><h1>No decks</h1>${btn('new-deck','Create your first deck','primary')}</section>`);return}
 const due=queue(cards(),direction,data.settings,data.history.filter(h=>h.deckId===d.id)).length;
 const unfinished=(data.editorDrafts||[]).map(r=>btn('resume-editor',`Resume · ${esc(r.deck.title.trim()||'Untitled draft')}`,'ghost small',`data-draft-id="${esc(r.id)}" data-deck-id="${esc(r.deckId||'')}"`)).join('');
 shell(`<section class="deck-head"><div><h1>${esc(d.title)}</h1></div><div class="row">${btn('edit-deck','Edit deck','secondary')}${btn('export-deck','Share deck','ghost')}</div></section>${unfinished?`<div class="row saved-drafts">${unfinished}</div>`:''}<div class="study-toolbar"><label>Answer with <select id="direction"><option value="forward" ${direction==='forward'?'selected':''}>Definitions / backs</option><option value="reverse" ${direction==='reverse'?'selected':''}>Terms / fronts</option></select></label><label class="check"><input type="checkbox" id="starOnly" ${starOnly?'checked':''}> Starred only</label><label class="check"><input type="checkbox" id="random" ${random||mode==='review'?'checked':''}> Shuffle</label><label class="check"><input type="checkbox" id="strict" ${strict?'checked':''}> Exact grading</label></div><nav class="modes" aria-label="Study modes">${modes.map(([id,label])=>btn('mode',label+(id==='review'?` <span class="pill">${due}</span>`:''),mode===id?'selected':'',`data-mode="${id}"`)).join('')}</nav><section id="study" class="study-area"></section>`);renderStudy();renderCards();for(const id of ['direction','starOnly','random'])document.querySelector('#'+id).disabled=mode==='test'&&!!session?.questions||id==='random'&&mode==='review'}
function renderCards(){const el=document.querySelector('#cards-list');if(!el)return;const list=deck().cards.filter(c=>normalizeSearch(c).includes(search.toLowerCase()));el.innerHTML=list.map(c=>`<article class="card-row ${c.suspended?'suspended':''}"><button class="star ${c.starred?'is-starred':''}" data-action="star" data-id="${esc(c.id)}" aria-label="${c.starred?'Unstar':'Star'} ${esc(c.term)}" aria-pressed="${!!c.starred}">${icon('star')}</button><div>${media(c.term,c.termImage)}${c.tags?.length?`<small class="tags">${esc(c.tags.join(' · '))}</small>`:''}</div><div>${media(c.definition,c.definitionImage)}${c.notes?`<small>${esc(c.notes)}</small>`:''}</div><button class="ghost small" data-action="edit-card" data-id="${esc(c.id)}">Edit</button></article>`).join('')||'<p class="empty-small">No cards match. Try a different search.</p>'}
function normalizeSearch(c){return `${c.term} ${c.definition} ${c.tags?.join(' ')} ${c.notes||''}`.toLowerCase()}
function renderStudy(){
 const el=document.querySelector('#study');if(!el)return;
 if(mode==='test'&&!session)restoreTest();
 if(session?.questions){drawTest(el);return}
 if(!cards().length){el.innerHTML=`<div class="empty-small"><p>${starOnly?'No starred cards.':'No cards available.'}</p>${btn('edit-deck','Edit deck','secondary')}</div>`;return}
 if(session){drawSession();return}
 if(mode==='flashcards'){start();return}
 if(mode==='test'){testSetup();return}
 el.innerHTML=`<div class="mode-intro">${mode==='party'?'<label class="party-input">Players (one per line)<textarea id="players" rows="3">Player 1\nPlayer 2</textarea></label>':''}${mode==='review'?`<span class="review-count">${queue(cards(),direction,data.settings,data.history.filter(h=>h.deckId===selected)).length} cards ready</span>`:''}${btn('start','Start','primary')}${['match','sprint','blocks','gravity','charms'].includes(mode)&&data.records[deck().id+mode]?`<small class="record">Best: ${esc(data.records[deck().id+mode])}</small>`:''}</div>`;
}
function start(){const pool=cards(),sessionKey=JSON.stringify([selected,mode]),list=random?shuffleCycle(pool,lastShown.get(sessionKey)):[...pool];if(mode==='test'){startTest();return}if(mode==='review'){const q=queue(cards(),direction,data.settings,data.history.filter(h=>h.deckId===selected));session={list:shuffle(q),index:0,done:0,initial:q.length,reveal:false,direction};drawSession();return}if(mode==='flashcards'){session={list,index:0,reveal:false,direction};drawSession();return}if(mode==='match'){const pairs=shuffle(cards()).slice(0,6).map((c,i)=>{const f=face(c,direction);return {id:String(i),front:visibleFaceKey(f.prompt,f.promptImage),back:visibleFaceKey(f.answer,f.answerImage),face:f}});session={pairs,tiles:shuffle(pairs.flatMap(p=>[{key:uid(),pairId:p.id,side:0,visible:p.front,...p.face},{key:uid(),pairId:p.id,side:1,visible:p.back,...p.face}])),chosen:null,matched:[],matchedPairs:[],mistakes:0,started:Date.now(),direction};timer=setInterval(updateClock,100);drawSession();return}
 if(mode==='charms'){session={list:shuffle(list),index:0,board:Array.from({length:25},()=>Math.floor(Math.random()*4)),chosen:null,direction,moves:0,score:0,answered:0,attempts:0,hits:0,feedback:null};drawSession();return}
 if(mode==='blocks'){session={list:shuffle(list).slice(0,12),cleared:[],index:0,direction,mistakes:0,attempts:0,hits:0,feedback:null};drawSession();return}
 let players=[];if(mode==='party'){players=(document.querySelector('#players')?.value||'').split('\n').map(s=>s.trim()).filter(Boolean).slice(0,8);if(players.length<2){toast('Add at least two players.');return}}
 session={list:['learn','write','spell'].includes(mode)?list:shuffle(list),index:0,mastered:Object.create(null),total:list.length,attempts:0,hits:0,feedback:null,started:Date.now(),deadline:Date.now()+(mode==='gravity'?15000:60000),lives:3,players:players.map(name=>({name,score:0})),turn:0,direction};if(mode==='sprint'||mode==='gravity')timer=setInterval(tick,100);drawSession();if(mode==='spell')speakCurrent()}
function current(){return session?.list?.[session.index%session.list.length]}
function contextTitle(){return modes.find(m=>m[0]===mode)[1]}
function progress(){const pending=direction!==studyDirection()||!!session.starOnly!==starOnly;return `<div class="session-top"><span>${esc(contextTitle())}</span><span>${mode==='review'?`${session.done} reviewed · ${session.list.length-session.index} ready`:mode==='flashcards'?`${session.index+1} / ${session.list.length}`:mode==='learn'?`${Object.values(session.mastered).filter(v=>v>=2).length} / ${session.total||session.list.length} mastered`:mode==='party'?`${esc(session.players[Math.floor(session.turn/5)].name)} · question ${session.turn%5+1}/5`:mode==='sprint'?'<span id="clock">60s</span>':mode==='gravity'?`${session.lives} lives · <span id="clock">15s</span>`:mode==='blocks'?`${session.cleared.length}/${session.list.length} blocks cleared`:`${session.hits||0} correct`}</span>${pending?'<small class="muted">Changes apply next session.</small>':''}</div>`}
function drawSession(){const el=document.querySelector('#study');if(!el||!session)return;if(session.starOnly===undefined)session.starOnly=starOnly;if(mode==='match'){drawMatch(el);return}if(mode==='charms'){drawCharms(el);return}if(mode==='test'){drawTest(el);return}if(mode==='review'&&session.index>=session.list.length){finish('You’re up to date.','Come back when your next reviews are ready. Again returns a card in 1 minute; Good on a new card returns it in 10 minutes.');return}
 const c=current(),f=face(c,studyDirection());if(!c)return;if(['flashcards','learn','write','spell'].includes(mode))lastShown.set(JSON.stringify([selected,mode]),c.id);
 if(mode==='flashcards'||mode==='review'){const now=Date.now();el.innerHTML=`${progress()}<button class="study-card ${session.reveal?'revealed':''}" data-action="flip" aria-label="${session.reveal?'Show question':'Reveal answer'}"><span class="side-label">${session.reveal?'Answer':studyDirection()==='forward'?'Term / front':'Definition / back'}</span><div>${media(session.reveal?f.answer:f.prompt,session.reveal?f.answerImage:f.promptImage,'large-face')}${additionalInfo(c.additionalInfo)}</div><span class="flip-hint">Click to flip · Space</span></button><div class="study-controls">${btn('speak',icon('sound')+' Listen','ghost')}${btn('session-star',icon('star')+(c.starred?' Starred':' Star'),'ghost')}${mode==='review'?btn('bury','Bury until tomorrow','ghost'):btn('autoplay',session.auto?'Pause autoplay':'Autoplay','ghost')}</div>${session.reveal&&c.notes?`<p class="note">${esc(c.notes)}</p>`:''}${mode==='review'?session.reveal?`<div class="ratings">${[1,2,3,4].map((r,i)=>btn('rate',`<strong>${['Again','Hard','Good','Easy'][i]}</strong><small>${intervalLabel(schedule(c.schedule?.[studyDirection()],r,now),now)} · ${r}</small>`,`rating rating-${r}`,`data-rating="${r}"`)).join('')}</div>`:btn('flip','Show answer','primary'): `<div class="flash-nav">${btn('prev','Previous','secondary',session.index===0?'disabled':'')}${btn('swap-session',icon('swap')+' Reverse direction','ghost')}${btn('next',session.index===session.list.length-1?'Finish':'Next','primary')}</div>`}`;return}
 if(mode==='blocks'){el.innerHTML=`${progress()}<div class="blocks-board">${session.list.map((card,i)=>btn('block',session.cleared.includes(i)?icon('check'):esc(face(card,studyDirection()).prompt||'Image card'),`block ${i===session.index?'current':''} ${session.cleared.includes(i)?'cleared':''}`,`data-index="${i}" ${session.cleared.includes(i)?'disabled':''}`)).join('')}</div><div id="question-pane"></div>`;drawQuestion(document.querySelector('#question-pane'),c,f,'written');return}
 el.innerHTML=`${progress()}${mode==='gravity'?'<div class="fall-track"><div id="falling" class="falling-token">'+esc(f.prompt||'Image prompt')+'</div></div>':''}<div id="question-pane"></div>`;const type=mode==='learn'?(session.mastered[c.id]||0)<1&&session.list.length>1?'choice':'written':mode==='sprint'||mode==='party'?'choice':'written';drawQuestion(document.querySelector('#question-pane'),c,f,type);updateClock()}
function drawQuestion(el,c,f,type){if(!session.question||session.question.cardId!==c.id){const options=shuffle([f.answer,...shuffle(session.list.filter(x=>x.id!==c.id)).map(x=>face(x,studyDirection()).answer).filter((a,i,arr)=>a!==f.answer&&arr.indexOf(a)===i).slice(0,3)]);session.question={cardId:c.id,type,options};if(!f.answer.trim())session.question.type='self'}const q=session.question,fb=session.feedback;
 el.innerHTML=`<div class="question"><span class="side-label">${mode==='spell'?'Listen and spell the answer':q.type==='choice'?'Choose the answer':q.type==='self'?'Recall the image':'Type the answer'}</span>${mode==='spell'?btn('speak',icon('sound')+' Play audio','audio-button'):media(f.prompt,f.promptImage,'question-face')}${additionalInfo(c.additionalInfo)}${mode==='spell'?`<details><summary>Show prompt</summary>${media(f.prompt,f.promptImage)}</details>`:''}${fb?`<div class="feedback ${fb.ok?'success':'failure'}" role="status"><strong>${fb.ok?'That’s right.':'Keep this one in mind.'}</strong>${!fb.ok||q.type==='self'?media(f.answer,f.answerImage):''}${c.notes?`<small>${esc(c.notes)}</small>`:''}</div>${btn('continue',fb.ok?'Continue · any key':'Continue','primary')}${!fb.ok&&fb.history?btn('accept-practice','I was correct','secondary'):''}`:q.type==='choice'?`<div class="choices">${q.options.map((o,i)=>btn('answer',`<span>${i+1}</span>${esc(o||'Image-only answer')}`,'choice',`data-answer="${esc(o)}"`)).join('')}</div>`:q.type==='self'?`${btn('show-image','Reveal image answer','primary')}`:`<form id="answer-form" class="answer-form"><input id="answer" autocomplete="off" value="${esc(session.answerInput||'')}" placeholder="Your answer…" aria-label="Your answer" required><button class="primary" type="submit">Check answer</button></form>`}</div>`;
 if(!fb&&q.type==='written')document.querySelector('#answer')?.focus();if(fb)document.querySelector('[data-action="continue"]')?.focus()}
function answer(value,override){if(!session||session.feedback)return;const c=current(),f=face(c,studyDirection()),q=session.question;const ok=override??(q?.type==='choice'?value===f.answer:correct(value,f.answer,session.strict??strict));session.attempts++;session.hits+=ok?1:0;session.feedback={ok,previousMastery:session.mastered?.[c.id]||0,history:logPractice(c,ok,mode)};saver.request();if(mode==='learn')session.mastered[c.id]=ok?(session.mastered[c.id]||0)+1:0;if(mode==='party')session.players[Math.floor(session.turn/5)].score+=ok?1:0;if(mode==='gravity'){if(!ok)session.lives--;session.deadline=Date.now()+15000}if(mode==='blocks'){if(ok)session.cleared.push(session.index);else session.mistakes++}drawSession()}
function acceptPractice(){
 if(!session?.feedback?.history||session.feedback.ok)return;
 const feedback=session.feedback;feedback.ok=true;feedback.history.ok=true;session.hits++;
 if(mode==='learn')session.mastered[current().id]=feedback.previousMastery+1;
 if(mode==='party')session.players[Math.floor(session.turn/5)].score++;
 if(mode==='gravity')session.lives++;
 if(mode==='blocks'){session.mistakes--;session.cleared.push(session.index)}
 save();drawSession();
}
function advance(){
 if(!session?.feedback)return;
 if(mode==='gravity'&&session.lives<=0){finish('Round complete.',`${session.hits} answers saved before the words fell.`,session.hits);return}
 if(mode==='gravity')session.deadline=Date.now()+15000;
 const wasCorrect=session.feedback.ok,answeredId=current().id;
 if(['write','spell'].includes(mode)&&wasCorrect){session.passed=session.passed||[];session.passed.push(answeredId)}
  if(mode==='charms'){session.answered++;if(wasCorrect)session.moves++;session.feedback=null;session.question=null;session.input='';session.answerInput='';session.index=(session.index+1)%session.list.length;drawSession();return}
 session.feedback=null;session.question=null;session.answerInput='';
 if(mode==='blocks'){if(session.cleared.length===session.list.length){finish('A clear board.',`${session.list.length} blocks cleared · ${session.mistakes} mistakes.`,session.list.length-session.mistakes);return}session.index=session.list.findIndex((_,i)=>!session.cleared.includes(i));drawSession();return}
 if(mode==='party'){session.turn++;if(session.turn===session.players.length*5){const results=[...session.players].sort((a,b)=>b.score-a.score);finish('Everyone’s turn is complete.',results.map(p=>`${p.name}: ${p.score}/5`).join(' · '));return}}
 if(mode==='learn'){
  const oldIndex=session.index,remaining=session.list.filter(c=>session.mastered[c.id]<2);
  if(remaining.length<session.list.length){session.list=remaining;if(!remaining.length){finish('You know this set.',`${session.total} cards answered correctly twice. Try spaced review to keep it in memory.`);return}session.index=Math.min(oldIndex,remaining.length-1)}
  else if(oldIndex===session.list.length-1){if(random)session.list=shuffleCycle(session.list,answeredId);session.index=0}
  else session.index=oldIndex+1;
  drawSession();return;
 }
  session.index=(session.index+1)%session.list.length;
  if(['write','spell'].includes(mode)&&session.index===0&&session.attempts>=session.list.length){const missed=session.list.filter(c=>!session.passed?.includes(c.id));if(!missed.length){finish('Practice complete.',`${session.hits}/${session.attempts} answers correct. All cards recalled.`);return}session.list=random?shuffle(missed):missed;session.index=0;session.passed=[]}
  drawSession();if(mode==='spell')speakCurrent()
 }
function logPractice(c,ok,source){const entry={id:uid(),at:Date.now(),deckId:deck().id,cardId:c.id,direction:studyDirection(),source,ok};data.history.push(entry);return entry}
function finish(title,description,score){const previous=session;if(timer){clearInterval(timer);timer=null}if(score!==undefined){const key=deck().id+mode;if(mode==='match'){if(!data.records[key]||score<parseFloat(data.records[key]))data.records[key]=`${score.toFixed(1)}s`}else if(!data.records[key]||score>parseFloat(data.records[key]))data.records[key]=`${score} points`;save()}session={finished:true};document.querySelector('#study').innerHTML=`<div class="complete"><div class="completion-mark">${icon('check')}</div><h2>${esc(title)}</h2><p>${esc(description)}</p>${btn('restart','Practice again','primary')}${btn('return','Back to mode','ghost')}${previous?.attempts?`<small>${previous.attempts} attempts this session</small>`:''}</div>`}
function rate(r){if(!session?.reveal||mode!=='review')return;const c=current(),old=c.schedule?.[studyDirection()];c.schedule=c.schedule||{};c.schedule[studyDirection()]=schedule(old,r);data.history.push({at:Date.now(),deckId:deck().id,cardId:c.id,direction:studyDirection(),rating:r,source:'review',wasNew:!old,ok:r!==1});session.index++;session.done++;session.reveal=false;save();drawSession()}
async function speakCurrent(){const c=current();if(!c)return;const f=face(c,studyDirection()),text=mode==='spell'?f.answer:session.reveal?f.answer:f.prompt;if(!text.trim()){toast('This side has an image but no text to read.');return}try{await speakText(text.split('|')[0],data.settings.voiceLang||'en-US')}catch(e){toast(e.message)}}
function drawMatch(el){el.innerHTML=`<div class="session-top"><span>Match the pairs</span><span id="clock">0.0s</span></div><div class="match-board">${session.tiles.map(t=>{const done=session.matched.includes(t.key);return `<button data-action="tile" data-key="${esc(t.key)}" class="match-tile ${done?'matched':''} ${session.chosen===t.key?'chosen':''}" ${done?'disabled':''}>${media(t.side?t.answer:t.prompt,t.side?t.answerImage:t.promptImage)}</button>`}).join('')}</div><p class="game-hint">Choose one term and its definition. ${session.mistakes} mismatches.</p>`;updateClock()}
function tile(key){const t=session.tiles.find(x=>x.key===key);if(!t||session.matched.includes(key))return;if(!session.chosen){session.chosen=key;drawSession();return}const first=session.tiles.find(x=>x.key===session.chosen);if(first.key===key){session.chosen=null;drawSession();return}const front=first.side===0?first:t,back=first.side===1?first:t;const pair=first.side!==t.side&&session.pairs.find(p=>!session.matchedPairs.includes(p.id)&&p.front===front.visible&&p.back===back.visible);if(pair){session.matchedPairs.push(pair.id);session.matched.push(first.key,t.key);if(session.matched.length===session.tiles.length){const sec=(Date.now()-session.started)/1000;finish('Everything connected.',`${sec.toFixed(1)} seconds · ${session.mistakes} mismatches.`,sec);return}}else{session.mistakes++;toast('Those don’t match. Try another pair.')}session.chosen=null;drawSession()}
function updateClock(){const el=document.querySelector('#clock');if(!el||!session)return;el.textContent=mode==='match'?`${((Date.now()-session.started)/1000).toFixed(1)}s`:`${Math.max(0,Math.ceil((session.deadline-Date.now())/1000))}s`;if(mode==='gravity'){const p=Math.min(1,1-(session.deadline-Date.now())/15000);document.querySelector('#falling')?.style.setProperty('top',`${p*100}%`)}}
function tick(){if(!session||session.finished||mode==='gravity'&&session.feedback)return;updateClock();if(Date.now()>=session.deadline){if(mode==='sprint')finish('A minute well spent.',`${session.hits} correct answers in 60 seconds.`,session.hits);else if(mode==='gravity'){session.lives--;if(!session.lives){finish('Round complete.',`${session.hits} correct answers.`,session.hits);return}session.feedback={ok:false};session.deadline=Date.now()+15000;toast('A word fell. One life lost.');drawSession()}}}
function testSetup(){
 const config=data.testConfigs?.[selected];if(config){testCount=config.count;testTypes=[...config.types]}
 document.querySelector('#study').innerHTML=`<div class="test-setup"><div class="test-config">${[['choice','Multiple choice'],['written','Written answers'],['tf','True / false'],['matching','Matching']].map(([id,label])=>`<label class="check"><input type="checkbox" data-test-type="${id}" ${testTypes.includes(id)?'checked':''}>${label}</label>`).join('')}<label>Questions <input type="number" id="test-count" min="1" max="1000" value="${testCount}"></label></div>${btn('start','Generate test','primary')}</div>`;
}
function startTest(){
 const types=[...document.querySelectorAll('[data-test-type]:checked')].map(el=>el.dataset.testType);
 const count=Number(document.querySelector('#test-count')?.value);
 if(!Number.isInteger(count)||count<1||count>1000){toast('Choose a whole number from 1 to 1000.');return}
 if(!types.length){toast('Choose at least one question type.');return}
 const questions=makeTest(cards(),direction,types,count);
 testTypes=types;testCount=count;data.testConfigs=data.testConfigs||{};data.testConfigs[selected]={count,types:[...types]};
 session={questions,submitted:false,direction,strict,starOnly};rememberTest();drawSession();
}
function rememberTest(){
 if(mode!=='test'||!session?.questions)return;
 data.testDrafts=data.testDrafts||{};data.testDrafts[selected]=structuredClone(session);
 clearTimeout(testSaveTimer);testSaveTimer=null;save();
}
function restoreTest(){
 const draft=data.testDrafts?.[selected];
 if(!draft||!Array.isArray(draft.questions)||!draft.questions.length||draft.questions.length>1000||!['forward','reverse'].includes(draft.direction))return;
 const ids=new Set(deck().cards.map(c=>c.id));
 if(draft.questions.some(q=>!ids.has(q.cardId)||typeof q.prompt!=='string'||typeof q.answer!=='string'||typeof q.input!=='string'||!['choice','written','tf','matching'].includes(q.type)||!Array.isArray(q.options)||q.options.some(v=>typeof v!=='string')))return;
 session=structuredClone(draft);direction=session.direction;strict=!!session.strict;starOnly=!!session.starOnly;
}
function updateTestInput(target){
 if(mode!=='test'||!session?.questions||session.submitted||!/^q\d+$/.test(target.name||''))return;
 const q=session.questions[Number(target.name.slice(1))];if(!q)return;
 q.input=target.value;data.testDrafts=data.testDrafts||{};data.testDrafts[selected]=structuredClone(session);saver.request();
}
function rememberTestConfig(){
 if(mode!=='test'||session?.questions)return;
 const count=Number(document.querySelector('#test-count')?.value),types=[...document.querySelectorAll('[data-test-type]:checked')].map(el=>el.dataset.testType);
 if(!Number.isInteger(count)||count<1||count>1000)return;
 testCount=count;testTypes=types;data.testConfigs=data.testConfigs||{};data.testConfigs[selected]={count,types};save();
}
function drawTest(el){const s=session;el.innerHTML=`<div class="session-top"><span>${s.questions.length} questions · Practice test</span>${btn('new-test','New test','secondary small')}</div>${s.submitted?`<div class="test-score"><h2>${s.questions.filter(q=>grade(q,session.strict??strict)).length} / ${s.questions.length}</h2><p>${Math.round(s.questions.filter(q=>grade(q,session.strict??strict)).length/s.questions.length*100)}% correct. Review your answers below.</p>${btn('test-missed','Practice missed cards','secondary')}</div>`:''}<form id="test-form">${s.questions.map((q,i)=>{const ok=s.submitted&&grade(q,session.strict??strict);return `<article class="test-question ${s.submitted?(ok?'test-correct':'test-wrong'):''}"><div class="question-number">${i+1}. <span>${{choice:'Multiple choice',written:'Written',tf:'True / false',matching:'Matching'}[q.type]}</span>${s.submitted?`<strong>${ok?'Correct':'Review'}</strong>`:''}</div>${media(q.prompt,q.promptImage,'test-prompt')}${additionalInfo(q.additionalInfo)}${q.type==='choice'?`<div class="test-choices">${q.options.map((o,j)=>`<label><input type="radio" name="q${i}" value="${esc(o)}" ${q.input===o?'checked':''} ${s.submitted?'disabled':''}>${esc(o)}</label>`).join('')}</div>`:q.type==='tf'?`<p>${esc(q.statement)}</p><div class="row">${['true','false'].map(v=>`<label class="check"><input type="radio" name="q${i}" value="${v}" ${q.input===v?'checked':''} ${s.submitted?'disabled':''}>${v==='true'?'True':'False'}</label>`).join('')}</div>`:q.type==='matching'?`<select name="q${i}" aria-label="Match question ${i+1}" ${s.submitted?'disabled':''}><option value="">Select a match…</option>${q.options.map(o=>`<option ${q.input===o?'selected':''} value="${esc(o)}">${esc(o)}</option>`).join('')}</select>`:`<input name="q${i}" value="${esc(q.input)}" placeholder="Your answer…" aria-label="Answer question ${i+1}" ${s.submitted?'disabled':''}>`}${s.submitted&&!ok?`<div class="answer-key"><small>Correct answer</small>${media(q.type==='tf'?String(q.truth):q.answer,q.answerImage)}${btn('accept-answer','I was correct','ghost small',`data-question="${i}"`)}</div>`:''}</article>`}).join('')}${!s.submitted?'<button type="submit" class="primary">Submit test</button>':''}</form>`}
function drawCharms(el){const s=session,c=current(),f=face(c,studyDirection());el.innerHTML=`<div class="session-top"><span>Charms · ${s.score} points</span><span>${s.moves} swaps earned · ${s.answered}/10 questions</span></div><div class="charms-layout"><div><div class="charms-board">${s.board.map((v,i)=>btn('charm','<span class="charm-shape shape-'+v+'"></span>',`charm ${s.chosen===i?'chosen':''}`,`data-index="${i}" aria-label="Tile ${i+1}, shape ${v+1}"`)).join('')}</div><p class="game-hint">Select adjacent tiles to swap. A match of three clears them. Earn swaps by answering questions.</p>${s.answered>=10?btn('finish-charms','Finish game','secondary'):''}</div><div id="charm-question"></div></div>`;if(s.answered<10)drawQuestion(document.querySelector('#charm-question'),c,f,'written');else document.querySelector('#charm-question').innerHTML='<h3>All questions complete.</h3><p>Use your remaining swaps, then finish.</p>'}
function charm(i){const s=session;const redraw=()=>{const restore=s.answerHadFocus,selection=s.answerSelection;drawSession();if(restore){const input=document.querySelector('#answer');input?.focus();if(input&&selection)input.setSelectionRange(...selection)}s.answerHadFocus=false};if(s.chosen===null){s.chosen=i;redraw();return}const a=s.chosen;s.chosen=null;if(!s.moves){toast('Answer a question to earn a swap.');redraw();return}if(!(Math.floor(a/5)===Math.floor(i/5)&&Math.abs(a-i)===1||Math.abs(a-i)===5)){toast('Choose adjacent tiles.');redraw();return}[s.board[a],s.board[i]]=[s.board[i],s.board[a]];s.moves--;const matches=new Set();for(let r=0;r<5;r++)for(let c=0;c<5;c++){const p=r*5+c;if(c<3&&s.board[p]===s.board[p+1]&&s.board[p]===s.board[p+2])[p,p+1,p+2].forEach(v=>matches.add(v));if(r<3&&s.board[p]===s.board[p+5]&&s.board[p]===s.board[p+10])[p,p+5,p+10].forEach(v=>matches.add(v))}s.score+=matches.size*10;matches.forEach(p=>s.board[p]=Math.floor(Math.random()*4));redraw()}


async function fingerprint(d){const content={title:d.title,description:d.description,cards:d.cards.map(c=>[c.id,c.term,c.definition,c.termImage,c.definitionImage,c.additionalInfo,c.notes,c.tags,c.starred,c.suspended])};const bytes=new TextEncoder().encode(JSON.stringify(content));return [...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('')}
function storeEditorDraft(id,deckId,deck,base){data.editorDrafts=data.editorDrafts||[];const record={id,deckId,updatedAt:Date.now(),baseFingerprint:base,deck:structuredClone(deck)};const index=data.editorDrafts.findIndex(r=>r.id===id);if(index<0)data.editorDrafts.push(record);else data.editorDrafts[index]=record;saver.request()}
function persistEditorDraft(){if(view==='editor'&&draft&&editorDraftId)storeEditorDraft(editorDraftId,data.decks.some(d=>d.id===draft.id)?draft.id:null,draft,draftBaseFingerprint)}
async function editor(id,resumeId){stop();data.editorDrafts=data.editorDrafts||[];const existing=data.decks.find(d=>d.id===id);const record=data.editorDrafts.find(r=>resumeId?r.id===resumeId:id?r.deckId===id:!r.deckId);editorDraftId=record?.id||uid();draft=record?structuredClone(record.deck):existing?structuredClone(existing):{id:editorDraftId,title:'',description:'',color:'green',cards:[emptyCard(),emptyCard()]};draftBaseFingerprint=record?.baseFingerprint??(existing?await fingerprint(existing):null);view='editor';persistEditorDraft();renderEditor()}
function emptyCard(){return {id:uid(),term:'',definition:'',termImage:'',definitionImage:'',notes:'',additionalInfo:'',tags:[],starred:false,suspended:false,schedule:{}}}
function renderEditor(){renderEditorBase();document.querySelector('.editor-meta').insertAdjacentHTML('afterend',`<div class="authoring-tools">${btn('cloze','Create fill-in-the-blank cards','secondary')}${btn('occlusion','Create image occlusion cards','secondary')}</div>`)}
function clozeView(){shell(`<section class="editor"><h1>Fill-in-the-blank cards</h1><p>Wrap each answer in double braces. Each blank becomes a separate card, with the other answers visible.</p><label>Passage<textarea id="cloze-text" rows="7" placeholder="The {{mitochondria}} produce {{ATP}}." aria-label="Cloze passage"></textarea></label><div class="row authoring-tools">${btn('make-cloze','Generate cards','primary')}${btn('back-editor','Back to editor','ghost')}</div><p class="small muted">Cards are generated as ordinary front/back cards so they work in every study mode. Nested or numbered Anki cloze syntax is not supported.</p></section>`)}
function makeCloze(){const text=document.querySelector('#cloze-text').value;const matches=[...text.matchAll(/\{\{([^{}]+)\}\}/g)];if(!matches.length){toast('Wrap at least one answer in {{double braces}}.');return}matches.forEach((m,i)=>{let n=0;const term=text.replace(/\{\{([^{}]+)\}\}/g,(_,answer)=>n++===i?'[ … ]':answer);draft.cards.push({...emptyCard(),term,definition:m[1],notes:text.replace(/\{\{([^{}]+)\}\}/g,'$1'),tags:['cloze']})});persistEditorDraft();renderEditor();toast(`${matches.length} fill-in-the-blank cards added. Save the deck to keep them.`)}
function occlusionView(){shell(`<section class="editor"><h1>Image occlusion</h1><p>Choose a diagram, drag a rectangle over a label, and enter its answer. Each rectangle becomes a card with a masked front and the original image on the back.</p><label class="upload-label">Choose diagram<input type="file" id="occlusion-file" accept="image/png,image/jpeg,image/webp,image/gif"></label><div id="mask-stage" class="mask-stage"><p>Select an image to begin.</p></div><label>Answer for this region<input id="mask-answer" placeholder="e.g. Left ventricle"></label><div class="row authoring-tools">${btn('add-mask','Add this region as a card','primary')}${btn('back-editor','Back to editor','ghost')}</div><p class="small muted">Rectangle masks only. Your original image stays attached to every card. Save the deck when you finish.</p></section>`)}
async function loadMask(file){const url=await readImage(file);if(!url)return;const img=new Image();await new Promise((res,rej)=>{img.onload=res;img.onerror=()=>rej(Error('Could not decode this image.'));img.src=url});occlusion={img,url,rect:null};const stage=document.querySelector('#mask-stage');stage.innerHTML='<canvas id="mask-canvas" aria-label="Drag over the image to mask a label"></canvas>';const canvas=document.querySelector('#mask-canvas');canvas.width=img.naturalWidth;canvas.height=img.naturalHeight;const ctx=canvas.getContext('2d');ctx.drawImage(img,0,0);let startPoint=null;const pos=e=>{const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height}};canvas.addEventListener('pointerdown',e=>{startPoint=pos(e);canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!startPoint)return;const p=pos(e);occlusion.rect={x:Math.max(0,Math.min(startPoint.x,p.x)),y:Math.max(0,Math.min(startPoint.y,p.y)),w:Math.abs(p.x-startPoint.x),h:Math.abs(p.y-startPoint.y)};ctx.drawImage(img,0,0);const r=occlusion.rect;ctx.fillStyle='#236349d9';ctx.fillRect(r.x,r.y,r.w,r.h);ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.strokeRect(r.x,r.y,r.w,r.h)});canvas.addEventListener('pointerup',()=>startPoint=null)}
function addMaskCard(){const answer=document.querySelector('#mask-answer').value.trim();if(!occlusion?.rect||occlusion.rect.w<5||occlusion.rect.h<5){toast('Drag a rectangle over the image first.');return}if(!answer){toast('Enter the answer for this region.');return}const canvas=document.createElement('canvas'),img=occlusion.img,r=occlusion.rect;canvas.width=img.naturalWidth;canvas.height=img.naturalHeight;const ctx=canvas.getContext('2d');ctx.drawImage(img,0,0);ctx.fillStyle='#236349';ctx.fillRect(r.x,r.y,r.w,r.h);ctx.fillStyle='white';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`${Math.max(12,Math.min(r.w,r.h)*.65)}px Segoe UI`;ctx.fillText('?',r.x+r.w/2,r.y+r.h/2);const termImage=canvas.toDataURL('image/png');if(termImage.length>16*1024*1024){toast('The diagram is too large. Use a smaller image.');return}draft.cards.push({...emptyCard(),term:'Name the hidden region.',definition:answer,termImage,definitionImage:occlusion.url,tags:['image-occlusion']});document.querySelector('#mask-answer').value='';toast('Region added. Draw another rectangle, or go back and save your deck.')}
function renderEditorBase(){shell(`<section class="editor"><div class="section-head"><div><h1>${data.decks.some(d=>d.id===draft.id)?'Edit deck':'New deck'}</h1></div><div class="row">${btn('back-editor','Back','ghost')}${btn('discard-editor','Discard draft','danger ghost')}${btn('save-deck','Save deck','primary')}</div></div><div class="editor-meta"><label>Deck title<input data-draft="title" value="${esc(draft.title)}" placeholder="e.g. Biology · Chapter 4" required maxlength="200"></label><label>Description<input data-draft="description" value="${esc(draft.description)}" placeholder="What are you learning?" maxlength="1000"></label></div><div class="editor-labels"><span>Term / front</span><span>Definition / back</span></div><div id="editor-cards">${draft.cards.map((c,i)=>`<article class="edit-row" id="edit-${esc(c.id)}"><div class="edit-number">${i+1}</div><div class="edit-side"><textarea data-card="${esc(c.id)}" data-field="term" aria-label="Term ${i+1}" placeholder="Term or question" rows="3">${esc(c.term)}</textarea>${imageEditor(c,'termImage',i)}</div><div class="edit-side"><textarea data-card="${esc(c.id)}" data-field="definition" aria-label="Definition ${i+1}" placeholder="Definition or answer (use | for alternatives)" rows="3">${esc(c.definition)}</textarea>${imageEditor(c,'definitionImage',i)}<label class="additional-info-field">Additional info (optional)<textarea data-card="${esc(c.id)}" data-field="additionalInfo" rows="2" aria-label="Additional info ${i+1}">${esc(c.additionalInfo||'')}</textarea></label></div><button class="icon-button remove-card" data-action="remove-card" data-id="${esc(c.id)}" aria-label="Remove card ${i+1}">${icon('close')}</button><details class="card-extra"><summary>Notes, tags & card options</summary><div class="extra-fields"><label>Extra notes<textarea data-card="${esc(c.id)}" data-field="notes" rows="2">${esc(c.notes)}</textarea></label><label>Tags (comma separated)<input data-card="${esc(c.id)}" data-field="tags" value="${esc(c.tags?.join(', '))}"></label><label class="check"><input type="checkbox" data-card="${esc(c.id)}" data-field="suspended" ${c.suspended?'checked':''}> Suspend from study</label><label class="check"><input type="checkbox" data-card="${esc(c.id)}" data-field="starred" ${c.starred?'checked':''}> Star this card</label></div></details></article>`).join('')}</div>${btn('add-card',icon('plus')+' Add a card','secondary wide')}${data.decks.some(d=>d.id===draft.id)?`<div class="danger-zone">${btn('delete-deck','Delete this deck','danger ghost')}</div>`:''}</section>`)}
function imageEditor(c,field,i){return `<div class="image-edit">${c[field]?`<img src="${esc(c[field])}" alt="Card ${i+1} attached image">${btn('remove-image','Remove image','ghost small',`data-id="${esc(c.id)}" data-field="${field}"`)}`:''}<label class="upload-label">${c[field]?'Replace':'Add'} image<input type="file" accept="image/png,image/jpeg,image/webp,image/gif" data-image-card="${esc(c.id)}" data-image-field="${field}"></label></div>`}
async function readImage(file){if(!file)return;if(file.size>8*1024*1024)throw Error('Choose an image smaller than 8 MB.');if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type))throw Error('Use PNG, JPEG, WebP or GIF images.');return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Could not read that image.'));reader.readAsDataURL(file)})}
async function saveDeck(){if(!draft.title.trim()){toast('Give your deck a title.');document.querySelector('[data-draft="title"]').focus();return}const valid=draft.cards.filter(c=>c.term.trim()||c.definition.trim()||c.termImage||c.definitionImage);if(!valid.length){toast('Add at least one card.');return}for(const c of valid)if((!c.term.trim()&&!c.termImage)||(!c.definition.trim()&&!c.definitionImage)){toast('Each card needs text or an image on both sides.');document.querySelector('#edit-'+CSS.escape(c.id))?.scrollIntoView({block:'center'});return}const record=data.editorDrafts?.find(r=>r.id===editorDraftId),latest=data.decks.find(d=>d.id===draft.id);let committed={...draft,cards:valid};if(latest&&record?.baseFingerprint&&await fingerprint(latest)!==record.baseFingerprint){committed.id=uid();committed.title+=' (draft copy)';toast('The deck changed while this draft was open. Your edits will be saved as a separate copy.')}else if(latest){const current=new Map(latest.cards.map(c=>[c.id,c]));committed.cards=valid.map(c=>({...c,schedule:current.get(c.id)?.schedule||{},buriedUntil:current.get(c.id)?.buriedUntil}))}const index=data.decks.findIndex(d=>d.id===draft.id);if(committed.id===draft.id&&index>=0)data.decks[index]=committed;else data.decks.push(committed);if(record)data.editorDrafts=data.editorDrafts.filter(r=>r.id!==record.id);selected=committed.id;draft=null;editorDraftId=null;draftBaseFingerprint=null;view='deck';const ok=await save();if(!ok&&record)data.editorDrafts.push(record);overview();toast(ok?'Deck saved. Ready when you are.':'Changes remain here; retry the save or export a backup.')}
function importView(){stop();view='import';shell(`<section class="import-page"><h1>Import cards</h1><div class="import-grid"><div><h2>Paste cards</h2><label>Deck title<input id="import-title" placeholder="Name your imported deck"></label><label>Separator<select id="separator"><option value="tab">Tab (Quizlet / Anki text)</option><option value="comma">Comma (CSV)</option><option value="semicolon">Semicolon</option></select></label><label class="check"><input type="checkbox" id="import-header"> First row contains column headings</label><textarea id="import-text" rows="10" aria-label="Paste cards" placeholder="Term&#9;Definition&#10;Another term&#9;Another definition"></textarea><p class="muted small">Two columns: front and back. Optional third column: notes. Quoted multiline CSV fields are supported. APKG files must first be exported as text in Anki.</p>${btn('paste-import','Create deck from text','primary')}</div><div class="file-import"><h2>Open a file</h2><label>JSON backup action<select id="json-import-mode"><option value="add">Add decks and progress</option><option value="restore">Replace this library</option></select></label><p>JSON library backup, CSV, TSV, or TXT.</p><label class="file-drop">${icon('book')}<span>Choose a file</span><input id="import-file" type="file" accept=".json,.csv,.tsv,.txt"></label><p class="small muted">Replacing keeps the current library as the previous local copy.</p></div></div></section>`)}
function importRows(text,title,delimiter,header=false){const rows=parseDelimited(text,delimiter);if(header)rows.shift();if(!rows.length)throw Error('No cards found. Paste at least one pair.');if(rows.some(r=>r.length<2||!r[0].trim()||!r[1].trim()))throw Error('Each row needs a term and definition. Check the separator.');const d={id:uid(),title:title.trim()||'Imported deck',description:'Imported from text',color:'green',cards:rows.map(r=>({...emptyCard(),term:r[0],definition:r[1],notes:r[2]||''}))};data.decks.push(d);selected=d.id;save();view='deck';overview();toast(`${d.cards.length} cards imported.`)}
function mergeImport(value,choice='add'){value=decodeLibrary(value);validateLibrary(value);if(choice==='restore'){if(!confirm('Replace this library with the backup? The current library will remain as the previous local copy.'))return;data=value;data.settings={newLimit:20,reviewLimit:200,...data.settings};data.history=data.history||[];data.records=Object.assign(Object.create(null),data.records||{});data.testConfigs=Object.assign(Object.create(null),data.testConfigs||{});data.testDrafts=Object.assign(Object.create(null),data.testDrafts||{});data.studyPreferences=data.studyPreferences||[];data.editorDrafts=data.editorDrafts||[];selected=data.decks[0]?.id;stop();save();view='deck';overview();toast('Backup restored.');return}const imported=structuredClone(value.decks),deckMap=new Map(),used=new Set(data.decks.map(d=>d.id));for(let i=0;i<imported.length;i++){const old=value.decks[i].id;let next=old;if(used.has(next)){next=uid();imported[i].title+=' (imported copy)'}used.add(next);deckMap.set(old,next);imported[i].id=next}data.decks.push(...imported);const historyIds=new Map();for(const h of value.history||[])if(deckMap.has(h.deckId)){const id=uid();if(h.id)historyIds.set(h.id,id);data.history.push({...h,id,deckId:deckMap.get(h.deckId)})}data.testConfigs=data.testConfigs||Object.create(null);data.testDrafts=data.testDrafts||Object.create(null);data.studyPreferences=data.studyPreferences||[];data.testConfigs=Object.assign(Object.create(null),data.testConfigs);data.testDrafts=Object.assign(Object.create(null),data.testDrafts);const configs=Object.create(null),drafts=Object.create(null);for(const [id,c] of Object.entries(data.testConfigs))Object.defineProperty(configs,id,{value:c,writable:true,enumerable:true,configurable:true});for(const [id,d] of Object.entries(data.testDrafts))Object.defineProperty(drafts,id,{value:d,writable:true,enumerable:true,configurable:true});for(const [old,id] of deckMap){if(value.testConfigs?.[old])Object.defineProperty(configs,id,{value:structuredClone(value.testConfigs[old]),writable:true,enumerable:true,configurable:true});if(value.testDrafts?.[old]){const saved=structuredClone(value.testDrafts[old]);for(const q of saved.questions||[])if(q.historyId&&historyIds.has(q.historyId))q.historyId=historyIds.get(q.historyId);Object.defineProperty(drafts,id,{value:saved,writable:true,enumerable:true,configurable:true})}for(const [game] of modes){const score=value.records?.[old+game];if(score!==undefined)data.records[id+game]=score}}data.testConfigs=configs;data.testDrafts=drafts;for(const pref of value.studyPreferences||[])if(deckMap.has(pref.deckId))data.studyPreferences.push({...pref,deckId:deckMap.get(pref.deckId)});for(const r of value.editorDrafts||[]){const copy=structuredClone(r);if(copy.deckId){if(!deckMap.has(copy.deckId))continue;copy.deckId=deckMap.get(copy.deckId);copy.deck.id=copy.deckId}else{copy.id=uid();copy.deck.id=copy.id}data.editorDrafts.push(copy)}selected=imported[0]?.id||selected;save();view='deck';overview();toast(`${imported.length} decks imported with their study progress.`)}
async function download(value,name){try{await exportLibrary(value,name)}catch(e){toast('Export failed: '+e.message)}}
function settingsView(){stop();view='settings';const now=Date.now(),reviews=data.history.filter(h=>h.source==='review'),today=reviews.filter(h=>new Date(h.at).toDateString()===new Date().toDateString()),good=reviews.filter(h=>h.ok).length;const bars=Array.from({length:14},(_,i)=>{const date=new Date(now-(13-i)*DAY);return {date,count:reviews.filter(h=>new Date(h.at).toDateString()===date.toDateString()).length}});const max=Math.max(1,...bars.map(x=>x.count));shell(`<section class="settings-page"><h1>Settings</h1><div class="stats-line"><div><strong>${today.length}</strong><span>reviews today</span></div><div><strong>${reviews.length}</strong><span>total reviews</span></div><div><strong>${reviews.length?Math.round(good/reviews.length*100)+'%':'—'}</strong><span>recall accuracy</span></div></div><h2>The last two weeks</h2><div class="activity-chart" aria-label="Daily review counts for 14 days">${bars.map(b=>`<div title="${b.date.toLocaleDateString()}: ${b.count} reviews"><span style="height:${Math.max(3,b.count/max*100)}%"></span><small>${b.date.getDate()}</small></div>`).join('')}</div><div class="settings-fields"><h2>Daily review limits</h2><p>Limits apply per deck, per direction. Learning cards keep their short review steps.</p><label>New cards per day<input type="number" id="new-limit" min="0" max="1000" value="${data.settings.newLimit}"></label><label>Review cards per day<input type="number" id="review-limit" min="0" max="10000" value="${data.settings.reviewLimit}"></label><label>Read-aloud language<select id="voice-lang">${[['en-US','English'],['es-ES','Spanish'],['fr-FR','French'],['de-DE','German'],['it-IT','Italian'],['ja-JP','Japanese'],['zh-CN','Chinese'],['ko-KR','Korean'],['hi-IN','Hindi']].map(([id,label])=>`<option value="${id}" ${(data.settings.voiceLang||'en-US')===id?'selected':''}>${label}</option>`).join('')}</select></label>${btn('save-settings','Save settings','primary')}</div><div class="storage-info"><h2>Storage & backup</h2><p>Cards, images, and progress are saved locally. A previous copy is retained after each save.</p><div class="row">${btn('backup',icon('download')+' Export a full backup','secondary')}${btn('retry-save','Retry local save','ghost')}</div></div></section>`)}
async function action(a,el){try{if(a==='cloze'){clozeView();return}if(a==='make-cloze'){makeCloze();return}if(a==='occlusion'){occlusionView();return}if(a==='add-mask'){addMaskCard();return}if(a==='back-editor'){occlusion=null;renderEditor();return}if(a==='reload'){location.reload();return}if(a==='select'){persistEditorDraft();stop();selected=el.dataset.id;random=shuffleChoice(selected,mode);view='deck';search='';if(mode==='test')restoreTest();overview()}else if(a==='home'){persistEditorDraft();stop();view='deck';overview()}else if(a==='new-deck')await editor();else if(a==='edit-deck')await editor(selected);else if(a==='resume-editor')await editor(el.dataset.deckId||undefined,el.dataset.draftId);else if(a==='edit-card'){const id=el.dataset.id;await editor(selected);document.querySelector('#edit-'+CSS.escape(id))?.scrollIntoView({block:'center'})}else if(a==='save-deck')await saveDeck();else if(a==='leave-editor'){persistEditorDraft();draft=null;editorDraftId=null;view='deck';overview()}else if(a==='discard-editor'){if(confirm('Discard this draft?')){data.editorDrafts=data.editorDrafts.filter(r=>r.id!==editorDraftId);draft=null;editorDraftId=null;draftBaseFingerprint=null;view='deck';save();overview()}}else if(a==='add-card'){draft.cards.push(emptyCard());persistEditorDraft();renderEditor();document.querySelector('#editor-cards .edit-row:last-child textarea')?.focus()}else if(a==='remove-card'){draft.cards=draft.cards.filter(c=>c.id!==el.dataset.id);persistEditorDraft();renderEditor()}else if(a==='remove-image'){draft.cards.find(c=>c.id===el.dataset.id)[el.dataset.field]='';persistEditorDraft();renderEditor()}else if(a==='delete-deck'){await deleteLibraryDeck(draft.id)}else if(a==='import'){persistEditorDraft();importView()}else if(a==='settings'){persistEditorDraft();settingsView()}else if(a==='save-settings'){const n=Number(document.querySelector('#new-limit').value),r=Number(document.querySelector('#review-limit').value);if(!Number.isInteger(n)||n<0||n>1000||!Number.isInteger(r)||r<0||r>10000)throw Error('Use whole numbers: 0–1000 new cards and 0–10000 reviews.');data.settings.newLimit=n;data.settings.reviewLimit=r;data.settings.voiceLang=document.querySelector('#voice-lang').value;await save();toast('Settings saved.')}else if(a==='retry-save')await save();else if(a==='backup')download(data,'freezlit-library-'+new Date().toISOString().slice(0,10)+'.json');else if(a==='export-deck')download({version:1,decks:[deck()],settings:data.settings,history:[],records:{}},deck().title.replace(/[^a-z0-9\-_]/gi,'-')+'.json');else if(a==='paste-import')importRows(document.querySelector('#import-text').value,document.querySelector('#import-title').value,{tab:'\t',comma:',',semicolon:';'}[document.querySelector('#separator').value],document.querySelector('#import-header').checked);else if(a==='mode'){stop();mode=el.dataset.mode;random=shuffleChoice(selected,mode);if(mode==='test')restoreTest();overview()}else if(a==='start')start();else if(a==='new-test'){stop();if(data.testDrafts)delete data.testDrafts[selected];save();testSetup()}else if(a==='restart'){stop();renderStudy();if(mode!=='test'&&mode!=='party')start()}else if(a==='return'||a==='end'){stop();renderStudy()}else if(a==='flip'){if(session&&!session.finished){session.reveal=!session.reveal;drawSession()}}else if(a==='next'){if(session.index===session.list.length-1)finish('You’ve seen the whole set.','Take a test, or start a scheduled review to make it stick.');else{session.index++;session.reveal=false;drawSession()}}else if(a==='prev'){session.index=Math.max(0,session.index-1);session.reveal=false;drawSession()}else if(a==='swap-session'){direction=direction==='forward'?'reverse':'forward';session.reveal=false;overview()}else if(a==='rate')rate(Number(el.dataset.rating));else if(a==='bury'){current().buriedUntil=Date.now()+DAY;session.index++;session.reveal=false;save();drawSession()}else if(a==='star'||a==='session-star'){const c=a==='star'?deck().cards.find(c=>c.id===el.dataset.id):current();c.starred=!c.starred;save();renderCards();if(a==='session-star')drawSession();else if(starOnly){stop();renderStudy()}}else if(a==='speak')speakCurrent();else if(a==='autoplay'){session.auto=!session.auto;if(timer){clearInterval(timer);timer=null}if(session.auto)timer=setInterval(()=>{if(!session||session.finished)return;if(!session.reveal){session.reveal=true}else if(session.index<session.list.length-1){session.index++;session.reveal=false}else{finish('Autoplay complete.','Try active recall next to test what you remember.');return}drawSession()},3500);drawSession()}else if(a==='answer')answer(el.dataset.answer);else if(a==='continue')advance();else if(a==='accept-practice')acceptPractice();else if(a==='show-image'){session.feedback={ok:false};drawSession();document.querySelector('[data-action="continue"]').outerHTML=btn('self-good','I recalled it','primary')+btn('self-again','Study it again','secondary')}else if(a==='self-good'||a==='self-again'){session.feedback=null;answer('',a==='self-good');advance()}else if(a==='tile')tile(el.dataset.key);else if(a==='block'){session.index=Number(el.dataset.index);session.question=null;session.feedback=null;drawSession()}else if(a==='charm')charm(Number(el.dataset.index));else if(a==='finish-charms')finish('Puzzle complete.',`${session.score} points earned.`,session.score);else if(a==='accept-answer'){const q=session.questions[Number(el.dataset.question)];if(!session.submitted||!q||q.accepted)return;q.accepted=true;const entry=q.historyId&&data.history.findLast(h=>h.id===q.historyId);if(entry)entry.ok=true;rememberTest();drawSession()}else if(a==='test-missed'){rememberTest();const missed=[...new Set(session.questions.filter(q=>!grade(q,session.strict??strict)).map(q=>q.cardId))].map(id=>deck().cards.find(c=>c.id===id));if(!missed.length){toast('No missed cards. Nicely done.');return}mode='write';session={list:missed,index:0,mastered:Object.create(null),total:missed.length,attempts:0,hits:0,feedback:null,passed:[]};drawSession()}}catch(e){toast(e.message)}}
app.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();action(el.dataset.action,el)}});
document.addEventListener('pointerdown',e=>{if(mode==='charms'&&e.target.closest('[data-action="charm"]')){const input=document.querySelector('#answer');if(input&&document.activeElement===input){session.answerHadFocus=true;session.answerSelection=[input.selectionStart,input.selectionEnd]}}},true);
app.addEventListener('input',e=>{const t=e.target;updateTestInput(t);if(t.id==='answer'&&session){session.answerInput=t.value;session.answerSelection=[t.selectionStart,t.selectionEnd]}if(t.id==='test-count'||t.dataset.testType)rememberTestConfig();if(t.id==='card-search'){search=t.value;renderCards()}if(t.dataset.draft)draft[t.dataset.draft]=t.value;if(t.dataset.card){const c=draft?.cards.find(c=>c.id===t.dataset.card);if(c)c[t.dataset.field]=t.dataset.field==='tags'?t.value.split(',').map(s=>s.trim()).filter(Boolean):t.type==='checkbox'?t.checked:t.value;if(view==='editor')persistEditorDraft()}});
app.addEventListener('change',async e=>{try{const t=e.target;updateTestInput(t);if(t.id==='test-count'||t.dataset.testType)rememberTestConfig();if(t.id==='occlusion-file'){await loadMask(t.files[0]);return}if(['direction','starOnly','random','strict'].includes(t.id)){if(t.id==='random'){random=t.checked;setShuffleChoice(selected,mode,random);save();return}if(t.id==='strict'){strict=t.checked;if(session){session.strict=strict;if(mode==='test')rememberTest();drawSession()}else overview();return}if(t.id==='direction')direction=t.value;if(t.id==='starOnly')starOnly=t.checked;if(session?.questions){overview();return}if(session){drawSession();return}overview()}else if(t.dataset.imageCard){const draftId=editorDraftId,deckId=draft?.id,cardId=t.dataset.imageCard,field=t.dataset.imageField;persistEditorDraft();const read=(async()=>{const image=await readImage(t.files[0]);if(!image)return;const record=data.editorDrafts?.find(r=>r.id===draftId),target=draft?.id===deckId?draft:record?.deck,card=target?.cards.find(c=>c.id===cardId);if(card){card[field]=image;if(draft===target&&view==='editor'){storeEditorDraft(draftId,data.decks.some(d=>d.id===deckId)?deckId:null,target,draftBaseFingerprint);renderEditor()}else if(record){record.deck=structuredClone(target);record.updatedAt=Date.now();saver.request()}}})();pendingImageReads.add(read);try{await read}finally{pendingImageReads.delete(read)}}else if(t.id==='import-file'){const file=t.files[0];if(!file)return;if(file.size>100*1024*1024)throw Error('Import files must be smaller than 100 MB.');const text=await file.text();if(file.name.endsWith('.json'))mergeImport(JSON.parse(text),document.querySelector('#json-import-mode')?.value||'add');else{document.querySelector('#import-text').value=text;document.querySelector('#import-title').value=file.name.replace(/\.[^.]+$/,'');document.querySelector('#separator').value=file.name.endsWith('.csv')?'comma':'tab';toast('File loaded. Check the separator and headings, then create the deck.')}}}catch(e){toast(e.message)}});
app.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='answer-form')answer(document.querySelector('#answer').value);if(e.target.id==='test-form'){const fields=new FormData(e.target);session.questions.forEach((q,i)=>{q.input=String(fields.get('q'+i)||'');q.historyId=logPractice(deck().cards.find(c=>c.id===q.cardId),grade(q,session.strict??strict),'test').id});session.submitted=true;rememberTest();drawSession();document.querySelector('#study').scrollIntoView({block:'start'})}});
document.addEventListener('keydown',e=>{if(view==='deck'&&session?.feedback?.ok&&!['INPUT','TEXTAREA','SELECT','A','SUMMARY'].includes(e.target.tagName)&&!(e.target.tagName==='BUTTON'&&['Enter',' '].includes(e.key))&&!e.repeat&&!e.isComposing&&!e.ctrlKey&&!e.altKey&&!e.metaKey&&!['Tab','Escape','Shift','Control','Alt','Meta','CapsLock','NumLock','ScrollLock','ContextMenu'].includes(e.key)&&!/^F\d+$/.test(e.key)){e.preventDefault();advance();return}if(['INPUT','TEXTAREA','SELECT','BUTTON','A','SUMMARY'].includes(e.target.tagName)||view!=='deck'||!session||session.finished)return;if(e.code==='Space'&&(mode==='review'||mode==='flashcards')){e.preventDefault();if(mode==='review'&&session.reveal)rate(3);else action('flip',{})}else if(mode==='review'&&session.reveal&&['1','2','3','4'].includes(e.key))rate(Number(e.key));else if(mode==='flashcards'&&e.key==='ArrowRight')action('next',{});else if(mode==='flashcards'&&e.key==='ArrowLeft')action('prev',{});else if(session.question?.type==='choice'&&!session.feedback&&['1','2','3','4'].includes(e.key)){const value=session.question.options[Number(e.key)-1];if(value!==undefined)answer(value)}});
const pendingImageReads=new Set();
window.freezlitFlushPendingWork=async()=>{if(view==='editor')persistEditorDraft();if(mode==='test'&&session?.questions)rememberTest();while(pendingImageReads.size)await Promise.all([...pendingImageReads]);return await saver.flush()};
window.addEventListener('beforeunload',e=>{if(dirty||saveError||pendingImageReads.size){e.preventDefault();e.returnValue='Unsaved changes'}});
async function boot(){try{const stored=await readLibrary();const migration=await removeLegacyStarter(stored===null?generateStarterLibrary():validateLibrary(stored));data=migration.library;data.settings={newLimit:20,reviewLimit:200,...data.settings};data.history=data.history||[];data.records=Object.assign(Object.create(null),data.records||{});data.testConfigs=Object.assign(Object.create(null),data.testConfigs||{});data.testDrafts=Object.assign(Object.create(null),data.testDrafts||{});data.studyPreferences=data.studyPreferences||[];data.editorDrafts=data.editorDrafts||[];selected=data.decks[0]?.id;random=shuffleChoice(selected,mode);overview();if(migration.changed||data.legacyCleanupPending){data.legacyCleanupPending=true;if(await save()){delete data.legacyCleanupPending;if(!await save())data.legacyCleanupPending=true}}else if(stored===null)await save()}catch(e){app.innerHTML=`<section class="fatal"><h1>Your library could not be opened.</h1><p>${esc(e.message)} The existing file has not been replaced.</p><p>Close the app and restore library.previous.json as library.json in your local app data folder, or relaunch after fixing storage access.</p><button data-action="reload">Try again</button></section>`}}
boot();


var libraryMenuTarget=null;
function closeLibraryMenu(restoreFocus=false){
 document.querySelector('#library-context-menu')?.remove();
 if(restoreFocus&&libraryMenuTarget?.isConnected)libraryMenuTarget.focus();
 libraryMenuTarget=null;
}
function openLibraryMenu(target,x,y){
 closeLibraryMenu();libraryMenuTarget=target;
 const menu=document.createElement('div');menu.id='library-context-menu';menu.className='library-context-menu';menu.setAttribute('role','menu');menu.setAttribute('aria-label','Deck actions');
 menu.innerHTML='<button type="button" role="menuitem" class="danger">Delete deck</button>';
 document.body.append(menu);
 const bounds=menu.getBoundingClientRect();menu.style.left=Math.max(8,Math.min(x,innerWidth-bounds.width-8))+'px';menu.style.top=Math.max(8,Math.min(y,innerHeight-bounds.height-8))+'px';
 menu.querySelector('button').onclick=()=>{const id=target.dataset.id;closeLibraryMenu(true);deleteLibraryDeck(id)};
 menu.querySelector('button').focus();
}
async function deleteLibraryDeck(id){
 const target=data.decks.find(d=>d.id===id);if(!target||!confirm(`Delete “${target.title}” and its cards?`))return;
 const active=selected===id||draft?.id===id;if(active)stop();
 data.decks=data.decks.filter(d=>d.id!==id);data.history=data.history.filter(h=>h.deckId!==id);
 if(data.testDrafts)delete data.testDrafts[id];if(data.testConfigs)delete data.testConfigs[id];if(data.editorDrafts)data.editorDrafts=data.editorDrafts.filter(r=>r.deckId!==id);
 for(const [key] of modes)delete data.records[id+key];
 if(active){selected=data.decks[0]?.id;draft=null;view='deck';overview()}
 else for(const button of document.querySelectorAll('.deck-link'))if(button.dataset.id===id)button.remove();
 await save();if(!saveError)toast('Deck deleted.');
}
app.addEventListener('contextmenu',e=>{const target=e.target.closest('.deck-link');if(!target)return;e.preventDefault();openLibraryMenu(target,e.clientX,e.clientY)});
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#library-context-menu'))closeLibraryMenu()});
document.addEventListener('keydown',e=>{
 const target=e.target.closest('.deck-link');
 if(target&&(e.key==='ContextMenu'||e.shiftKey&&e.key==='F10')){e.preventDefault();const rect=target.getBoundingClientRect();openLibraryMenu(target,rect.left+20,rect.bottom);return}
 if(e.key==='Escape'&&document.querySelector('#library-context-menu')){e.preventDefault();closeLibraryMenu(true)}
});
document.addEventListener('scroll',()=>closeLibraryMenu(),true);
window.addEventListener('resize',()=>closeLibraryMenu());
